// Serwist PWA service worker — handles precaching and runtime caching only.
// FCM push notifications are handled by a SEPARATE service worker:
//   /firebase-messaging-sw.js  (generated by scripts/generate-firebase-sw.js)
//   registered with scope /firebase-cloud-messaging-push-scope
// Do NOT add Firebase Messaging or onBackgroundMessage logic here.

import { defaultCache } from '@serwist/next/worker';
import type { PrecacheEntry, SerwistGlobalConfig } from 'serwist';
import { Serwist } from 'serwist';

declare global {
  interface WorkerGlobalScope extends SerwistGlobalConfig {
    __SW_MANIFEST: (PrecacheEntry | string)[] | undefined;
  }
}

declare const self: ServiceWorkerGlobalScope;

const serwist = new Serwist({
  precacheEntries: self.__SW_MANIFEST,
  skipWaiting: true,
  clientsClaim: true,
  navigationPreload: true,
  runtimeCaching: defaultCache,
});

serwist.addEventListeners();

console.log('[sw.ts] Serwist service worker loaded');
